export function escapeHtml(value: string): string {
  return value
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;')
}

function fill(template: string, values: string[], transform: (value: string) => string): string {
  return template.replace(/%%(\d+)%%/g, (_, i: string) => transform(values[Number(i)] ?? ''))
}

const oneLine = (value: string) => value.replace(/[\r\n]+/g, ' ')
const identity = (value: string) => value

